def RESULT {α : Type u} : result α → α :=
  @Classical.epsilon (result α → α) ⟨fun r => match r with | Clash t => t | Result t => t⟩
    (fun f => ∀ t, f (Result t) = t)

theorem RESULT_def {α : Type u} : ∀ t : α, RESULT (Result t) = t := by
  apply Classical.epsilon_spec (p := fun f : result α → α => ∀ t, f (Result t) = t)
  exact ⟨fun r => match r with | Clash t => t | Result t => t, fun _ => rfl⟩

def CLASH {α : Type u} : result α → α :=
  @Classical.epsilon (result α → α) ⟨fun r => match r with | Clash t => t | Result t => t⟩
    (fun f => ∀ t, f (Clash t) = t)

theorem CLASH_def {α : Type u} : ∀ t : α, CLASH (Clash t) = t := by
  apply Classical.epsilon_spec (p := fun f : result α → α => ∀ t, f (Clash t) = t)
  exact ⟨fun r => match r with | Clash t => t | Result t => t, fun _ => rfl⟩
